 FOR r IN SELECT * FROM jsonb_to_recordset($data_v51$[{"course":"swift","ordinal":1,"title":"let und var","theory":"let deklariert in Swift eine unveränderliche Bindung, var eine veränderliche. Die Entscheidung macht Absichten sichtbar.","example":"let name=\"Alex\"\nvar punkte=5","example_note":"punkte kann später neu zugewiesen werden, name nicht.","task":"Erkläre, welcher Wert veränderbar sein soll.","q1":{"question":"Welche Aussage erklärt „let und var“ richtig?","options":["Ein Optional kann einen Wert oder nil enthalten. Vor der Verwendung muss der Inhalt sicher entpackt werden.","let deklariert in Swift eine unveränderliche Bindung, var eine veränderliche. Die Entscheidung macht Absichten sichtbar.","guard let prüft eine notwendige Voraussetzung und verlässt bei Misserfolg frühzeitig den gültigen Bereich."],"correct":1,"explanation":"let deklariert in Swift eine unveränderliche Bindung, var eine veränderliche. Die Entscheidung macht Absichten sichtbar."},"q2":{"question":"Was zeigt das Beispiel zu „let und var“?","options":["name enthält derzeit keinen String; der Typ lässt diesen Zustand zu.","Nach dem guard kann der entpackte Benutzer ohne weitere Optionalprüfung verwendet werden.","punkte kann später neu zugewiesen werden, name nicht."],"correct":2,"explanation":"punkte kann später neu zugewiesen werden, name nicht."}},{"course":"swift","ordinal":2,"title":"Optional","theory":"Ein Optional kann einen Wert oder nil enthalten. Vor der Verwendung muss der Inhalt sicher entpackt werden.","example":"var name:String?=nil","example_note":"name enthält derzeit keinen String; der Typ lässt diesen Zustand zu.","task":"Modelliere einen fehlenden Spielernamen.","q1":{"question":"Welche Aussage erklärt „Optional“ richtig?","options":["Optional Binding mit if let macht einen vorhandenen Wert innerhalb eines Blocks sicher verfügbar.","Swift-Arrays speichern geordnete Elemente eines bestimmten Typs und können mit append erweitert werden.","Ein Optional kann einen Wert ode